 out=set()
 for k in range(4):
  b=[row[:] for row in arr]
  for _ in range(k): b=[list(row) for row in zip(*b[::-1])]
  for bb in (b,[row[::-1] for row in b]):
   out.add(frozenset((i,j) for i in range(3) for j in range(3) if bb[i][j]))
 return out
